package spark.sql.prac2

import org.apache.spark.sql.SparkSession

/**
* 把RDD转换为DataFrame并保存为不同格式的文件(csv、json、parquet、orc)
*/
object DataFrameSave2File {

def main(args: Array[String]): Unit = {

// 创建SparkSession 对象
val spark = SparkSession
.builder()
.appName("DataFrameSave2File")
.master("local[2]")
.getOrCreate()

// 从SparkSession 中获取SparkContext对象sc
val sc = spark.sparkContext

//创建一个RDD
val rdd = sc.parallelize(List( (1, "John"), (2, "Mary"), (3, "Smith") ) )

//隐式转换，
import spark.implicits._

//RDD转换为DataFrame
val df = rdd.toDF("id", "name")
df.show()
df.printSchema()

//将DataFrame保存为csv文件, 默认一行数据的多个字段以逗号,分隔
df.write.csv("output/prac2/csv1")
//将DataFrame保存为csv文件, 设置 一行数据的多个字段以|分隔
df.write.option("delimiter", "|").csv("output/prac2/csv2")
//将DataFrame保存为csv文件, 默认文件写入模式为error
//设置文件写入模式为overwrite:目录不存在直接写入, 目录存在直接覆盖原来的数据
//其他写入模式：1、append表示追加 2、error表示如果有目录存在,直接报错 3、ignore跳过, 表示如果有目录存在, 不保存
df.write.mode("overwrite").option("delimiter", ";").csv("output/prac2/csv3")

//隐式转换
import spark.implicits._
val df2 = df.select(($"id" + 4).as("id"), $"name", $"age", $"email")

df2.show()

//DataFrame写入mysql
df2.write
.mode("append")
.format("jdbc")
.option("url", "jdbc:mysql://master:3306/test?useSSL=false")
.option("driver", "com.mysql.jdbc.Driver")
.option("user", "root")
.option("password", "Root@321")
.option("dbtable", "user")
.save()

}

}
package spark.sql.prac2
