object DataFrameParquetPrac {

def main(args: Array[String]): Unit = {

// 创建SparkSession 对象
val spark = SparkSession
.builder()
.appName("DataFrameParquetPrac")
.master("local[2]")
.getOrCreate()

//读parquet文件
val df = spark.read.parquet("output/prac2/par1")
//读取orc文件
//val df = spark.read.orc("output/prac2/orc1")

df.show()

//对DataFrame的字段id 加 1
val df2 = df
.select( df("id")+1, df("name") )
.withColumnRenamed("(id + 1)", "id")
df2.show()

//保存为parquet文件
df2.write.parquet("output/prac2/par2")
//保存为parquet文件, 默认为snappy压缩，这里配置为gzip压缩
df.write.option("compression", "gzip").parquet("output/prac2/par3")

//保存为orc文件
df2.write.orc("output/prac2/orc2")

}
}

